from pathlib import Path
import json,hashlib,html,csv
p=Path(__file__).resolve().parent;root=p.parents[1]
web=json.loads((p/'web-manifest.json').read_text());urls={x['id']:x['url'] for x in web}
bom=json.loads((root/'ce-assemblies/microduck/current/bom.json').read_text())['record'];by={x['ref']:x['qty'] for x in bom['rows']}
local=['ce-assemblies/microduck/current/bom.json','spec/sourcing.json']
parts=[]
for slug,mesh in [('bearing-22x16x4','seeed_bearing__configuration__22x16x4'),('bearing-15x10x3','seeed_bearing__configuration_default')]:
 f=f'ce-parts/{slug}/iterations/v0.0.1/cad/interfaces.json';d=json.loads((root/f).read_text())['record']['interfaces'];it={i['name']:i for i in d};q=by['part:'+slug];parts.append({'slug':slug,'mesh_dimensions_id_od_width_mm':[it['bore']['nominal_mm'],it['od']['nominal_mm'],it['od']['ring_width_mm']],'per_robot_mjcf':q,'required_pieces_1_100_1000':[q*n for n in [1,100,1000]],'original_mpn':None,'original_shield_seal_material_grade_lubricant_clearance':None});local += [f,f'ce-parts/{slug}/sourcing.json',f'out/laneT/features/{mesh}.json',f'reference/pollen-microduck-rl/assets/{mesh}.stl']
rows=[]
def offer(part,route,code,closure,material,source,prices,stock,qualification):
 for n,q,price in zip([1,100,1000],parts[part]['required_pieces_1_100_1000'],prices):
  rows.append({'part':parts[part]['slug'],'robots':n,'required_pieces':q,'route':route,'order_code':code,'closure':closure,'material':material,'unit_price':price,'currency':'NZD' if source=='nz' else 'USD' if source in ['direct','vxb'] else None,'extended_parts_only':round(price*q,4) if price is not None else None,'stock_observation':stock,'quote_status':qualification,'url':urls[source]})
offer(0,'NZ Miniature Bearings distributor; manufacturer unverified','MR1622-ZZ / 00206030','two non-contact metal shields','GCr15','nz',[5.9,5.9,5.9],'Page says in stock; no quantity','Retail extrapolation, not volume offer or stock commitment; GST and freight extra')
offer(0,'SMB, stated authorized EZO UK distributor','ET2216','open','chrome steel','smb',[None]*3,'No product stock quantity observed','RFQ; exact dimensional/type candidate; brand/order suffix and original identity still require confirmation')
offer(0,'MVB Xiamen Power-Star, China manufacturer catalog','ET-2216','not specified on product page','not specified on product page','mvb',[None]*3,'No stock or prices observed','Dimensional candidate only; obtain drawing/closure/material/grade confirmation before comparing types')
offer(1,'Bearings Direct / AMPEC retail','6700 (interchange MR6700)','open','SAE52100, light oil','direct',[4.86,4.131,4.131],'721 pieces displayed; usually ships in 24 hours','1/100 robot demand below displayed count; 1000 robot demand exceeds by2279. 15% at50+ applied mathematically; stock and delivered quote not guaranteed')
offer(1,'VXB retail','6700 Open / UPC00193019072509','open','chrome steel','vxb',[7.77,5.439,None],'Structured data available=true; inventory_management=null; no quantity','Price7.77 confirmed structured product data despite reversed visible sale labels. 30% at100+;1000+OEM has no price,30–60day text. General processing5–10business days,10USD minimum; no invented OEM price')
offer(1,'SMB, stated authorized EZO UK distributor','6700','open','chrome steel','smb',[None]*3,'No product stock quantity observed','RFQ; source table explicitly3mm open,4mm shielded/sealed')
offer(1,'ZEN manufacturer catalog','61700','open','AISI52100','zen',[None]*3,'No stock or prices observed','RFQ manufacturer route;61700-C3 is separate clearance variant; not interchangeable without approval')
report={'revision':'MD-BEARINGS-20260908-A','status':'Research and conditional RFQ only; original installed bearings unidentified','date':'2026-09-08','quantities_basis':bom['counted_from'],'parts':parts,'offers_by_batch':rows,'correction_proposals':[{'paths':['spec/sourcing.json B11','ce-parts/bearing-15x10x3/sourcing.json'],'issue':'Existing assertion61700-2Z/FAG61700-2Z-HLC is10x15x3 is unsupported and contradicted. Primary ZEN 61700-2Z and authorized distributor SMB 6700ZZ are10x15x4. ABF FAG61700-2Z-HLC listing also states4mm. Do not offer as3mm replacement.','primary_sources':[urls['zen'],urls['smb']],'fag_distributor_corroboration':'https://www.abf.store/s/en/bearings/61700-2Z-HLC-FAG/702741'},{'paths':['spec/sourcing.json B10','ce-parts/bearing-22x16x4/component.json'],'issue':'MR1622-ZZ is a dimension-matched offer, not established original MPN. ET2216 without suffix is explicitly open in SMB catalog; alias lists cannot erase closure/material/clearance differences.'}],'identity_questions':['Photograph both bearing faces and packaging, read manufacturer/full suffix/lot; measure actual removed bore/OD/width. Mesh envelope is not specimen metrology.','Confirm open versus one/two shields or seals, steel grade, cage, lubricant, radial clearance, tolerance class and installed running torque. Do not assume ABEC equivalence or upgrade.','Reconcile real hardware count and all retainers/spacers/fasteners with MJCF visual count; mesh count is not a complete service BOM.','Request separate11/1100/11000 and3/300/3000piece quotations; include MOQ, pack rounding, stock date, traceability, sample inspection and destination-dependent freight/tax. No order commitment.'],'china_route':{'vendor':'MVB Xiamen Power-Star','url':urls['mvb'],'scope':'China manufacturer dimensional catalog candidate16x22x4; closure/material unconfirmed; destination not assumed'},'local_evidence':[{'path':f,'sha256':hashlib.sha256((root/f).read_bytes()).hexdigest()} for f in local],'web_evidence':web}
(p/'audit.json').write_text(json.dumps(report,indent=2)+'\n')
with (p/'conditional-rfq.csv').open('w',newline='') as f:w=csv.DictWriter(f,fieldnames=rows[0]);w.writeheader();w.writerows(rows)
e=html.escape
body='<h1>Microduck bearing sourcing / 轴承采购核查</h1><p>2026-09-08 · MD-BEARINGS-20260908-A</p><p><b>Conditional RFQ only. Original installed manufacturer, closure and grade remain unknown. 仅供询价，原机厂家、密封形式和等级未确认。</b></p><p>Published mesh envelopes and MJCF counts give 16×22×4 mm: 11 per robot (11 / 1,100 / 11,000 pieces); 10×15×3 mm: 3 per robot (3 / 300 / 3,000 pieces). Dimensions use ID×OD×width. They are not measurements of a physical specimen.</p><h2>Correction before purchasing / 采购前纠正</h2><p>The existing claim that 61700-2Z is a shielded 3 mm alternative is contradicted by current catalogs: ZEN 61700-2Z and SMB 6700ZZ are 4 mm wide. Open 61700/6700 is 3 mm. Do not add suffixes and assume unchanged width. Existing project records have not been mutated.</p><p>61700-2Z／6700ZZ的目录宽度为4mm，不是3mm；不能直接替换模型中的3mm轴承。ET2216开式与MR1622-ZZ双防尘盖也不能仅凭尺寸视为同一原装件。</p><h2>Conditional offers</h2><table><tr>'+''.join('<th>'+x+'</th>' for x in ['Route / code','Robots / pieces','Unit / subtotal','Status'])+'</tr>'
for r in rows:
 cost='RFQ' if r['unit_price'] is None else f"{r['currency']} {r['unit_price']} / {r['extended_parts_only']}"
 body+='<tr><td><a href="'+e(r['url'])+'">'+e(r['route'])+'</a><br>'+e(r['order_code']+'; '+r['closure'])+'</td><td>'+str(r['robots'])+' / '+str(r['required_pieces'])+'</td><td>'+e(cost)+'</td><td>'+e(r['stock_observation']+'; '+r['quote_status'])+'</td></tr>'
body+='</table><p>All prices are observed page values or explicitly calculated extensions, excluding unquoted freight/tax. Stock is not reserved. NZ volume totals simply extend retail pricing; VXB OEM totals remain unknown.</p><h2>Original identity and quotation questions</h2><ul>'+''.join('<li>'+e(x)+'</li>' for x in report['identity_questions'])+'</ul><p>请提供原机轴承两面及包装照片、完整料号、实测尺寸、开式／防尘盖／密封形式、材料、游隙、润滑和精度等级。大轴承按11／1100／11000件，小轴承按3／300／3000件分别报价，注明库存日期、最小订量、包装、交期及追溯。目的地未确认，运税分列；不构成订单。</p><p>Evidence hashes and exact sources: audit.json and web-manifest.json. Quantities and all routes: conditional-rfq.csv.</p>'
(p/'REPORT.html').write_text('<!doctype html><html><meta charset="utf-8"><title>Microduck bearing sourcing</title><style>body{font:16px system-ui;max-width:1200px;margin:40px auto;padding:20px}td,th{padding:12px;border:1px solid #ccc;vertical-align:top}table{border-collapse:collapse}a{color:#17637b}</style><body>'+body+'</body></html>')
assert [x['required_pieces_1_100_1000'] for x in parts]==[[11,1100,11000],[3,300,3000]]
assert len(rows)==21 and sum(r['extended_parts_only'] is not None for r in rows)==8
assert all(hashlib.sha256((p/x['file']).read_bytes()).hexdigest()==x['sha256'] for x in web)
